        abstractZh: "人类语言在词汇和句法形式上差异显著，却能够传递相似的语义内容；这种跨语言语义共性的神经基础仍不清楚。作者开发了多语言脑解码框架 SemDecoder，并分析来自 227 名参与者、覆盖中文、英文和法文的脑记录。研究发现，不同语言和个体的皮层语义表征保留了相似的内容间几何关系，形成共享的皮层语义几何。跨语言一致性从感觉运动皮层向高阶联合皮层逐渐增强，构成一条与大脑主功能梯度高度一致的共享语义几何梯度。模型不仅执行无目标语言神经训练数据的零样本迁移，还在目标语言数据受限时，把其他语言的语义结构用于文本解码；英文、中文和法文的迁移模型在所有测试数据比例上均优于只用同等目标语言数据训练的基线。在独立法语队列中，使用共享几何梯度高端的皮层输入也获得更好的篇章识别。结果建立了可泛化的多语言脑解码，并把稳定的皮层语义几何确定为跨语言语义共性的一个神经基础。",
        relevance: "论文事实：SemDecoder 在 227 名参与者和三种语言上比较皮层语义几何，并分别测试零样本跨语言迁移、少量目标语言数据迁移和独立法语队列的篇章识别；跨语言一致性及迁移贡献均沿感觉运动区到高阶联合区增强。研究推断：你的统一 fMRI—语言模型可以把语言特异表面形式与共享语义几何分开建模，并将目标语言数据比例、未知被试和未知语料设为三个正交泛化轴。",
