        abstractZh: "脑编码模型旨在根据刺激预测神经响应，主流方法通常冻结预训练主干，只拟合一个神经读出层。由于神经数据昂贵且有限，从头训练大模型或对任务预训练模型进行全量微调一直很困难。作者证明，参数高效微调能够用少量可训练参数有效适配超大规模预训练主干。为使计算可行，方法利用因果主干的结构，在一次前向传播中预测多个时间点，而不再反复使用滑动窗口，从而显著降低特征提取成本。该设计支持对最高 104B 参数的多模态主干进行神经适配。BrainLoRA 由低秩适配器和轻量读出层组成，在九种不同多模态主干上持续改善脑编码性能；在与既有最佳方法相同的 Qwen3-Omni 主干上，它以约 5% 的可训练参数取得作者报告的 Algonauts 2025 最佳公开结果。模态归因恢复出经典感觉拓扑，并显示神经适配提高了音频输入和主干内部跨模态混合的贡献。作者还开发多 LoRA 内核，在共享主干上并行训练适配器，使 200 多个适配模型的集成在写作时位居公开赛后排行榜第一。",
        relevance: "论文事实：BrainLoRA 用 CNeuroMod/Algonauts 2025 的自然电影 fMRI 适配九种多模态主干，规模最高达到 104B；因果批量预测、LoRA 和轻量读出共同降低计算成本，模态归因用于检查视觉、音频及跨模态贡献。研究推断：统一 fMRI 编解码模型可把共享大主干冻结，仅为模态、被试或数据集配置可组合的低秩适配器；但选择适配器时应同时看未知电影、未知被试和新数据集，而非只看同一挑战排行榜。",
