        abstractZh: "使用大型语言模型嵌入预测神经活动时间变化的叙事编码模型，常被用于评估大脑表征特定语义信息的程度；但这类分析通常把语义表征压缩成跨参与者汇总的单一拟合分数，忽视自然情境神经表征中丰富的个体差异和质性差异。研究使用 49 名参与者收听英文《小王子》有声书时的 fMRI，并以 GPT-2 不同层级和不同前瞻长度的嵌入训练编码模型，检验持续注意如何改变个体神经语义编码。GPT-2 第八层的高层嵌入在 122 个皮层及皮层下 ROI 中的 73 个呈现显著脑—模型对齐，主要集中于颞叶和默认模式网络。由已验证持续注意连接组预测模型得到的功能连接强度，与 18 个 ROI 的编码表现相关，最强关系位于岛叶以及控制和注意网络，没有 ROI 呈现显著相反关系。进一步按抽象层级拆分语义信息后，持续注意的神经标志选择性关联于额顶和注意网络中更高比例的高层主旨信息，而低层信息比例呈相反关系。持续注意得分还预测多个全脑网络对即将到来的叙事内容具有更强的预测性编码。结果表明，持续注意并非均匀放大神经语义编码，而是把表征转向更压缩、主旨化并支持内容预期的格式。",
        relevance: "论文事实：49 名参与者的叙事 fMRI 编码显示，持续注意连接组指标不仅关联总体模型拟合，还关联高层主旨信息占比与未来内容预测。研究推断：你的脑—语言模型可在共享语义表示之外增加个体状态变量，检查注意状态是否改变语义层级而非只缩放信号强度；评估时应分别报告低层词汇、句子意义、篇章主旨和前瞻信息。",
