        abstractZh: "揭示全脑神经动力学的低维表示及其与行为的关系，仍是神经科学的核心挑战。作者提出旋转成分分析（RCA），一种能够在单试次内优化检测低方差旋转模式的降维方法，并显示自发的全脑旋转动力学会约束线索诱发行为和学习。RCA 被应用于猴和人类运动皮层的放电数据、小鼠全皮层钙成像，以及人类 fMRI 和 MEG。小鼠中，从静息活动识别出的旋转模式能够预测线索诱发行为：随机时刻线索到达时的旋转相位，可预测动物随后是否拉杆。循环神经网络与一个最小二维反应学习模型共同说明，内在旋转模式如何成为反应和学习的动力学约束。研究还发现含两个旋转中心的双旋转模式，可在小鼠和人类数据中分离准备期与任务期动力学。相应模式也组织人类非运动任务中的神经活动；当主成分分析无法显示组间差异时，旋转不可逆性仍能捕捉早期精神病特征。作者据此把旋转动力学视为把持续脑状态转换为行为的低维坐标，并将 RCA 提出为检测生物和物理数据中隐蔽非互易动力学的通用工具。",
        relevance: "论文事实：RCA 在放电、钙成像、fMRI 和 MEG 上寻找低方差旋转模式，并在小鼠中将静息相位与随后行为、模型机制及学习联系起来。研究推断：可将 RCA 用于统一脑编解码模型的潜空间审计，检查被压低方差的动态变量是否仍预测刺激响应或解码错误；但人类 fMRI/MEG 上应先复现跨被试和跨 session 稳定性，再谈共享动力学。",
