        tags: ["fMRI", "LLM 表征", "自然对话", "语言产生与理解", "特征移除"],
        abstractZh: "大型语言模型（LLM）的脑对齐，为研究语言加工过程中 LLM 与人脑表征的相似性提供了一种途径。既有研究主要关注被动语言理解，而在说话者同时参与语言产生与理解的对话情境中，这种对齐仍知之甚少。本研究利用对话期间采集的 fMRI 数据，在不同 LLM 层和脑区中考察语言产生与理解期间的脑对齐。我们评估其与 LLM 表征内在维度（ID）的关联，以及若干可解释的语言和交际特征的贡献。结果揭示了语言产生与理解之间不同的脑对齐模式，以及脑对齐与 ID 在各加工模式相关脑区中的强关联。我们进一步表明，语言与交际特征的贡献也随加工模式、LLM 层和脑区而变化。",
        relevance: "论文事实：全文分析七名日语被试，按 session 留一进行三折评估，并比较 Llama-3.1、Gemma-2 和 GPT-OSS。中间层通常对齐较强；产生时感觉运动区、理解时听觉区呈不同层级模式，特征移除进一步拆解语言及交际信息的线性贡献。研究推断：统一脑—语言模型可以在共享语义核心之外，显式设置产生／理解状态分支；对 ROI 解释同时控制词汇、词性、发言时长及交际意图，以免把任务状态误当成语义机制。",
        limitation: "这是从文本表征预测 fMRI 的编码与解释分析，不是 fMRI→文本生成，也不是未知被试迁移。七名日语被试限制了外推范围；内在维度与脑对齐的相关不建立因果关系。移除可线性读取的特征不保证语义信息被完全消除，发音、听觉输入和对话角色也可能共同影响差异。当前为预印本。",
