        abstractZh: "研究目的：能够在新用户上无需校准便工作的想象语音解码器，将使非侵入式语音接口更加实用。我们检验头皮 EEG 记录中的想象语音内容能否跨人迁移，并考察单人准确率仍然偏低的原因。研究方法：我们分析 ds003626、KaraOne 和 2020 年国际脑机接口竞赛 Track 3 三个公开语料，使用通过断言强制保证划分完整性的协议，报告精确二项分布阈值、群体检验和自助法置信区间。我们在每名参与者上训练解码器，再测试所有其他参与者；在不使用分类器的情况下比较跨参与者表征几何，应用被试级对齐，并检验五种关于被试内性能上限的解释。主要结果：在 482 个有向参与者对中，没有任何一对通过多重比较校正；所有语料的平均跨人迁移准确率与机会水平的差异都在 0.006 以内，而全部被试内参考结果均高于机会水平。想象期相对刺激前静息的判别在伪迹和已过时间控制后可达到约 0.61，但其解码器把想象前的间隔也判为想象的频率与想象期相同，因此该对比反映刺激后的状态，而非想象本身。被试内，仅竞赛语料在所有参与者上均超过阈值，准确率为 0.3147、机会水平为 0.200；音节数只能解释其中很少一部分，但其频率特征未通过伪迹审计。研究意义：在这些语料中，想象语音内容无法通过我们考察的任何表示跨人迁移。每类试次数是唯一能够一致排列这些语料表现的变量，这支持优先建设更大的单条件数据集，而非继续只发展模型。",
        relevance: "论文事实：三语料、482 个有向被试对没有出现校正后可靠内容迁移；‘想象相对静息’的结果也无法区分想象与刺激后的其他状态。研究推断：你的共享语义核心与被试 adapter 应用完整 LOSO、留出 session 和同状态不同内容对照分别验证。共享潜空间的可视化、域对抗成功或二元状态判别，都不应替代未见被试的内容检索证据。",
