        abstractZh: "研究目的：头皮 EEG 想象语音解码研究通常用外显语音等阳性对照验证管线，并报告阴性结果，却不说明该管线能够检测多大的效应。研究方法：我们使用 ds003626（Thinking out loud）、KaraOne 和 2020 年国际脑机接口竞赛 Track 3，在通过断言保证划分完整性的协议下，借助伪迹通道子集、频带限制解码和试次选择，审计外显语音、发音器官准备和想象语音的解码。我们向真实记录中注入已知幅度的类别依赖效应，测量五类解码器的检测下限，并依据采集协议核对 ds003626 的标签。主要结果：在 ds003626 上，两枚唇部电极和八个外部通道的外显语音解码准确率分别达到 0.7430 和 0.7068，高于 128 通道头皮布局的 0.4231，而 8–30 Hz 频带内没有保留下可解码信号。其余两个语料的被试内准确率随频率单调上升，进入肌肉活动占主导的频段。在预先固定的判据下，频带功率逻辑回归能够检测注入幅度为 0.54 微伏的 8–30 Hz 去同步效应，而紧凑卷积网络 EEGNet 在被试内、最高 4.31 微伏时仍未检测到效应。ds003626 的条件编码与直观理解相反，类别编码在公开版本间发生过改变，条件还由每个 session 内的时间确定。研究意义：这些语料中的外显语音阳性对照主要受肌源信号驱动，不能验证神经解码管线。我们建议语音解码研究报告限制频带与伪迹通道准确率、准确率随频率变化的方向，以及实际测得的检测下限。",
