        abstractZh: "真实世界物体大小是物体知识的重要组成部分，但大脑如何把视觉输入、空间关系、记忆和语义尺度整合为大小表征仍不清楚。作者使用 50 名参与者观看手持物体图像时的全脑 fMRI，训练三维深度神经网络区分现实中较小与较大的物体，并与多体素模式分析比较。深度模型达到与传统多体素方法相当的预测表现。通过 Guided Grad-CAM 分析，作者发现支持大小判别的体素并不只位于通常与物体加工相关的腹侧枕颞皮层，而是分布于更广泛的脑区；这些区域还与临床病灶研究中出现物体大小知觉扭曲的区域重叠。结果支持这样一种观点：真实世界大小不是单一区域中的标签，而是由跨越视觉、空间、记忆与语义系统的非线性分布式整合产生。本文为 2026 年 2 月 bioRxiv 预印本的正式期刊版本，本期仅保留正式版。",
