        relevance: "论文事实：在六个 rs-fMRI 队列上，严格留一数据集评估显著降低年龄预测性能，并使复杂 SPD 方法与简单基线之间的优势收窄；年龄范围和队列差异是主要影响因素。研究推断：你的跨被试 fMRI→CLIP 或脑动力学模型也应增加 leave-one-dataset/site-out 轴，并同时报告域内、合并和整数据集外推结果；若语义性能只在合并交叉验证中成立，就不能声称模型具有数据集级泛化。",
