        abstractZh: "把 EEG 转换为 fMRI 对医学神经影像、临床脑状态监测和多模态神经解码具有重要意义，因为它试图从快速、易获取的电生理记录中推断具有空间组织的血流动力学活动。既有 EEG→fMRI 研究主要追求更强的解码器，但该问题还受表征接口不匹配制约：fMRI 响应具有延迟、时间积分和空间分布特性，而通用 EEG 编码往往把时间滞后、通道身份与频带结构纠缠在一起。作者提出多频带 EEG 潜在状态 token 化 MEL。该框架把每个目标 fMRI 响应锚定到此前的一段 EEG 历史，并按“时延—通道—频带”组织神经状态 token，从而保留原始坐标结构。通过显式描述血流动力学时延与频谱—空间动力学，MEL 用容量受控的读出层对齐与 fMRI 相关的 EEG 表征，而不是把收益完全寄托于扩大模型。VU EEG–fMRI 基准和外部 Oddball 数据上的实验显示，MEL 优于强 NeuroBOLT 基线；消融和控制进一步表明，提升来自结构化 EEG 表征，而不是信息泄漏、捷径统计或更大的解码器容量。",
        relevance: "论文事实：MEL 将目标 fMRI 之前的 EEG 历史显式拆成时延、通道和频带 token，并在内部及外部数据上优于 NeuroBOLT，同时用容量匹配和泄漏控制验证收益来源。研究推断：这为统一 fMRI–EEG 模型提供了比直接共享编码器更合理的接口：先保留 EEG 的时间/频带坐标，再把它映射到 fMRI 的空间—血流动力学状态；后续可将这种模态转换与共享 CLIP 语义目标联合训练，比较“预测 fMRI”是否真正提高脑到内容解码。",
