        abstractZh: "视觉神经科学近年来积累了大量自然图像脑响应数据，但静态图像缺少理解真实动态视觉所必需的时间维度。为支持对动态视觉事件知觉神经机制的研究，作者发布 EEG Moments Dataset（EMD）。该数据集包含 6 名参与者观看 1,102 段 3 秒自然视频（含音轨）时记录的 128 通道 EEG 和眼动数据；参与者保持中央注视。分析表明，EMD 的 EEG 响应包含可解码的刺激相关信息，与视频时间进程存在对应关系，并且基于不同特征空间的脑编码模型揭示了丰富的表征内容。更重要的是，EMD 与既有 BOLD Moments Dataset（BMD）使用相同的 1,102 段视频刺激；后者提供人类 fMRI 响应，因此两套数据可用于对动态视觉事件开展具有时间与空间分辨率的联合研究。作者公开原始和预处理 EEG、眼动数据、全部视频刺激与丰富元数据，并提供交互式代码教程。",
