        abstractZh: "精神分裂症包含阳性症状、阴性症状和认知损伤等部分独立的维度，但现有神经影像方法很少能同时提供个体级症状预测与可解释的脑区定位。作者提出一种可解释 AI 框架，通过自监督对比学习把高维静息态 fMRI 动力学映射到低维潜在流形，并设计新的归因方法定位对临床特征最具解码能力的脑区。该方法在两个独立的精神分裂症谱系队列上评估；无需症状标签训练得到的潜空间能够支持个体级症状严重程度和认知功能预测。归因图显示，疾病相关表征集中于前额叶、后部小脑和颞叶区域，与健康对照中以听觉、边缘和腹侧纹状体回路为主的潜空间组织不同。结果表明，自监督潜空间既可以表征分布式脑动力学，也可以在个体层面将临床症状预测映射回明确的解剖网络，为研究精神分裂症症状的个体化神经基础提供模型驱动的路径。",
        relevance: "论文事实：标签无关的自监督 rs-fMRI 潜空间在两个独立队列上支持症状和认知预测，并通过归因定位前额叶—小脑—颞叶特征。研究推断：你的模型解释也可以采用“先学习无标签脑动力学流形，再检验反事实类别效应如何投影到流形和脑区”的两阶段设计；但归因必须配合 ROI 删除、置换和外部验证，避免把漂亮的空间热图当作功能证据。",
