        abstractZh: "目标：EEG 基础模型通常通过重建或对比对齐较短的信号片段进行训练，再将局部表示汇聚为固定维度嵌入。本文检验这些嵌入是否保留了长程时间相关性；该相关性使用 alpha 频带包络的去趋势波动分析（DFA）指数进行量化，并进一步检验它是否影响跨人群迁移。方法：作者在两个分布外队列上探测五个涵盖原始波形输入和频谱输入架构的 EEG 基础模型——REVE、LaBraM、BENDR、CBraMod 和 BIOT，比较模型恢复 DFA 指数与静态 1/f 非周期斜率的能力。研究使用保持时间顺序和残差化控制，检验失败是否来自汇聚操作或非周期特征遮蔽；还在统一电极布局后开展零样本迁移，在三个队列之间比较冻结模型嵌入与 DFA 指数，其中加入一个西方参考队列。主要结果：五个基础模型都没有按正确时间顺序表征长程时间相关性。原始波形模型 REVE、LaBraM 和 BENDR 既不能恢复 DFA 指数，也不能恢复 1/f 斜率，R² 不超过 0.12，因此其探针本身缺少信息；明确的频谱—时间分离主要出现在频谱输入模型 CBraMod 和 BIOT 中，它们能够较强地恢复 1/f 斜率，R² 为 0.59–0.73，却不能跨队列恢复 DFA。经典 DFA 特征可以恢复该指数，R² 为 0.32–0.38，而其可靠性上限为 0.64；长程时间相关与非周期斜率基本正交，r=-0.06。在跨人群迁移中，冻结 REVE 嵌入未超过随机水平，西方队列到韩国队列的结果为 0.45；无量纲 DFA 指数呈现方向性迁移，但在家族错误率校正后未显著，其他四个模型也未一致复现。五个模型的表示都被记录站点轴主导，站点可解码率为 0.98–1.00，而随机水平为 0.50；相比之下，被模型丢弃的 DFA 指数具有更强站点稳健性，站点可解码率为 0.71。",
