        abstractZh: "脑机接口（BCI）中的脑电图（EEG）解码面临一个主要挑战：显著的被试间差异限制了有效的跨被试泛化。因此，实际系统仍主要依赖从头训练的被试专属模型，并需要对每名被试进行单独重新校准。近年来，EEG 基础模型成为应对这一限制的有前景方案；然而，即使是大规模预训练模型，也不能简单地作为固定特征提取器使用，在可靠应用于下游任务前仍需要额外适配。本文围绕这一问题研究有针对性的适配策略。作者以 REVE、LaBraM 和 LUNA 等近期 EEG 基础模型为基础，考察不同低秩适配策略对运动想象分类的影响。作者提出一种结构化解耦被试不变知识与被试特异神经特征的框架：将每个适配层中的低秩更新拆分为跨所有被试联合训练、用于捕捉共享任务表征的 Global adapter，以及分别吸收个体差异的 Subject-Specific adapter。为评估两条路径的贡献，作者比较了三种适配策略：（i）被试专属 LoRA，（ii）全局 LoRA，以及（iii）结合全局与被试专属适配器的 Stacked LoRA。在 BCI Competition IV-2a、PhysioNet Motor Imagery 和临床 Zuo2025 基准上的实验表明，Stacked LoRA 在绝大多数骨干模型和数据集组合中取得最高准确率。进一步分析显示，最优的全局—个体平衡取决于目标人群：对于规模大且多样的队列，共享适配器已经足够；而在临床记录中较高的跨 session 变异下，被试特异适配至关重要。",
